"""Read-only revised teardown verification; original failing captures unchanged."""
import argparse,hashlib,importlib.util,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('transport_conversation_analysis',HERE.parent/'persistent_conversation/analyze.py');base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
REFERENCES={'conversation_s48_transport':'conversation_s48','walking_s46_transport':'walking_native_s46'}

def analyze_case(run,case,plan):
 item,audit,data=base.analyze_case(run,case,plan);after=json.loads((run/'episode/result.json').read_text());old=ROOT/'experiments/social_navigation/benchmark/generated/persistent_conversation_20261029'/REFERENCES[case['id']];before=json.loads((old/'episode/result.json').read_text());receipts=after['server_shutdown'].get('transport_bridge_shutdown',{});children=receipts.get('bridges',[]);lines=(run/'episode/launch.log').read_text().splitlines();gz_ix=next((i for i,v in enumerate(lines) if v.startswith('[INFO] [gz-1]: process has finished cleanly')), -1);checks=item['checks'];checks['all_four_bridge_audit']=audit['checks'].get('ordered_launch_transport_bridge_exit') is True;checks['all_four_clean_before_gazebo']=len(children)==4 and all(v.get('clean') is True and v.get('record') in lines and 0<=lines.index(v['record'])<gz_ix for v in children);checks['single_ordered_bridge_signals']=[v['role'] for v in children]==['ground_truth','obstacle','camera_image','robot'] and all(v.get('signal')=='SIGINT' for v in children);checks['no_launch_or_cleanup_fallback']=after['ros_launch_shutdown']['status']=='STOPPED' and after['ros_launch_shutdown']['returncode']==0 and not after['cleanup']['signals'];checks['same_initial_ready']=before['ready']==after['ready']
 changed=sorted(k for k in before['source_sha256'].keys()&after['source_sha256'].keys() if before['source_sha256'][k]!=after['source_sha256'][k]);added=sorted(k for k in after['source_sha256'].keys()-before['source_sha256'].keys() if '/generated/' not in k);checks['only_teardown_common_sources_changed']=changed==['python/dynamuhsim/analysis/capture.py','python/dynamuhsim/runtime/capture.py','python/dynamuhsim/runtime/shutdown.py'];checks['only_transport_helper_added']=added==['python/dynamuhsim/runtime/transport_shutdown.py']
 item.update(status='PASS' if all(checks.values()) else 'FAIL',transport_shutdown=receipts,changed_common_sources=changed,added_non_run_sources=added,reference_id=REFERENCES[case['id']]);return item,audit,data

def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);plan=json.loads((HERE/'plan.json').read_text());raw=ROOT/plan['raw_root'];report=dict(schema='transport_order_result/1',cases=[],errors=[],training_ready=False,defaults_promoted=False,original_conversation_cohort_status='FAIL');audits={};media={}
 for case in plan['cases']:
  try:
   run=raw/case['id'];item,audit,data=analyze_case(run,case,plan);report['cases'].append(item);audits[case['id']]=audit;media[case['id']]=base.base.media.export(run,a.output)
  except Exception as error:report['errors'].append(dict(id=case['id'],error=type(error).__name__+': '+str(error)))
 report['status']='PASS' if len(report['cases'])==len(plan['cases']) and not report['errors'] and all(v['status']=='PASS' for v in report['cases']) else 'FAIL';report['bounded_collection_profile_eligible']=report['status']=='PASS' and json.loads((HERE.parent/'persistent_conversation/preflight_results.json').read_text())['status']=='PASS'
 for name,value in [('results.json',report),('audits.json',audits),('media_evidence.json',media)]: (a.output/name).write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
 cards=''
 for item in report['cases']:
  m=item['metric'];children=item['transport_shutdown']['bridges'];cards+=f"<article><h2>{item['id']}: {item['status']}</h2><p>Goal {m['status']}; {m['active_sim_s']:.2f}s; recoveries {m['max_action_recoveries']}; min robot/person surface gap {m['minimum_swept_robot_human_gap_m']*100:.1f}cm. Four clean bridge receipts: {sum(v.get('clean') is True for v in children)}/4.</p><video controls preload='metadata' src='{item['id']}.webm'></video></article>"
 (a.output/'index.html').write_text("<!doctype html><meta charset='utf-8'><title>Capture transport validation</title><style>body{background:#11232d;color:#eaf0f5;font:17px system-ui;max-width:1100px;padding:20px;margin:30px auto}article{border:1px solid #476577;padding:18px;margin:20px 0;border-radius:12px}video{width:100%}a{color:#7ee4c2}</style><h1>Kiểm chứng giữ nhóm và đóng bridge — "+report['status']+"</h1><p>Hai lượt mới trên phiên bản chỉ sửa teardown. Giữ nguyên mọi FAIL cũ. Video RGB thật từ Gazebo, phát mặc định1×thời gian mô phỏng. Đây là kiểm chứng có giới hạn trên máy hiện tại, chưa phải dữ liệu train.</p>"+cards+"<p>Cảnh trò chuyện dùng hợp đồng snapshot tuổi mục tiêu; kiểm tra đến đích/hết hạn NOT_EXERCISED. Walking vẫn dùng query verifier và lifecycle tự nhiên.</p><p><a href='results.json'>Results + bridge receipts</a> · <a href='audits.json'>Full audits</a> · <a href='../persistent_conversation/index.html'>Ba seed và lỗi cũ</a> · <a href='collection_profile.json'>Bounded collection recipe (if accepted)</a></p><script>document.querySelectorAll('video').forEach(v=>v.addEventListener('loadedmetadata',()=>v.playbackRate=.25));</script>")
 print(report['status'],[(v['id'],v['status'],[k for k,okay in v['checks'].items() if not okay]) for v in report['cases']],report['errors'])

if __name__=='__main__':main()
